#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s, t;
    cin >> N >> s >> t;

    // dp[i][a][b] = min ops for first i chars, a = char at i-1, b = char at i-2
    vector<vector<vector<int>>> dp(N + 1, vector<vector<int>>(2, vector<int>(2, INF)));

    // initial states: before first char we can think of sentinel values
    dp[0][0][0] = 0;
    dp[0][0][1] = 0;
    dp[0][1][0] = 0;
    dp[0][1][1] = 0;

    for (int i = 0; i < N; i++) {
        for (int c1 = 0; c1 < 2; c1++) {          // s[i-1]
            for (int c2 = 0; c2 < 2; c2++) {      // s[i-2]
                if (dp[i][c1][c2] == INF) continue;
                for (int cur = 0; cur < 2; cur++) {
                    // cannot have three same in a row
                    if (i >= 2 && c1 == c2 && c1 == cur) continue;
                    int cost = (cur != (t[i] - '0')) ? 1 : 0;
                    int nc1 = cur;
                    int nc2 = c1;
                    dp[i+1][nc1][nc2] = min(dp[i+1][nc1][nc2], dp[i][c1][c2] + cost);
                }
            }
        }
    }

    int ans = INF;
    for (int c1 = 0; c1 < 2; c1++) {
        for (int c2 = 0; c2 < 2; c2++) {
            ans = min(ans, dp[N][c1][c2]);
        }
    }
    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;
    int n = (int)s.size();

    const int INF = 1e9;

    // dp[i][a][b]:
    // after processing first i characters,
    // current built string's last two characters are a,b (for i>=2),
    // and minimum flips used.
    //
    // To handle small i uniformly, we build left to right and store states
    // as the whole prefix string's last up to 2 chars encoded by mask/len.
    //
    // state id:
    // 0 -> length 0
    // 1 -> "0"
    // 2 -> "1"
    // 3 -> "00"
    // 4 -> "01"
    // 5 -> "10"
    // 6 -> "11"
    //
    auto getLen = [&](int id) -> int {
        if (id == 0) return 0;
        if (id <= 2) return 1;
        return 2;
    };

    auto appendState = [&](int id, int c) -> int {
        int len = getLen(id);
        if (len == 0) {
            return c == 0 ? 1 : 2;
        } else if (len == 1) {
            int x = (id == 1 ? 0 : 1);
            if (x == 0 && c == 0) return 3;
            if (x == 0 && c == 1) return 4;
            if (x == 1 && c == 0) return 5;
            return 6; // 1,1
        } else {
            int x, y;
            if (id == 3) x = 0, y = 0;
            else if (id == 4) x = 0, y = 1;
            else if (id == 5) x = 1, y = 0;
            else x = 1, y = 1;

            // caller guarantees no triple equal after append
            if (y == 0 && c == 0) return 3;
            if (y == 0 && c == 1) return 4;
            if (y == 1 && c == 0) return 5;
            return 6;
        }
    };

    auto okAppend = [&](int id, int c) -> bool {
        int len = getLen(id);
        if (len < 2) return true;
        int x, y;
        if (id == 3) x = 0, y = 0;
        else if (id == 4) x = 0, y = 1;
        else if (id == 5) x = 1, y = 0;
        else x = 1, y = 1;
        return !(x == y && y == c);
    };

    vector<int> dp(7, INF), ndp(7, INF);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        fill(ndp.begin(), ndp.end(), INF);
        int target = t[i] - '0';

        for (int st = 0; st < 7; ++st) {
            if (dp[st] == INF) continue;

            // Final character must equal t[i], so choose c = target.
            int c = target;
            if (!okAppend(st, c)) continue;

            int nst = appendState(st, c);
            int cost = dp[st] + ((s[i] - '0') != c);
            ndp[nst] = min(ndp[nst], cost);
        }

        dp.swap(ndp);
    }

    int ans = INF;
    for (int st = 0; st < 7; ++st) ans = min(ans, dp[st]);
    cout << ans << '\n';
    return 0;
}

