#define MAXN 20
#define HASH_SIZE (1 << 22)

typedef struct Entry {
    char key[MAXN+1];
    int dist;
    struct Entry *next;
} Entry;

Entry *table[HASH_SIZE];

unsigned int hash_str(const char *s) {
    unsigned int h = 5381;
    while (*s) h = h * 31 + *s++;
    return h & (HASH_SIZE - 1);
}

int visited(const char *s, int dist) {
    unsigned int h = hash_str(s);
    for (Entry *e = table[h]; e; e = e->next)
        if (!strcmp(e->key, s)) return 1;
    Entry *e = malloc(sizeof(Entry));
    strcpy(e->key, s);
    e->dist = dist;
    e->next = table[h];
    table[h] = e;
    return 0;
}

char queue[2000000][MAXN+1];
int qdist[2000000];
int qhead, qtail;

int main() {
    char s[MAXN+1], t[MAXN+1];
    scanf("%s %s", s, t);
    int n = strlen(s);

    qhead = qtail = 0;
    strcpy(queue[qtail], s);
    qdist[qtail] = 0;
    qtail++;
    visited(s, 0);

    while (qhead < qtail) {
        char cur[MAXN+1];
        strcpy(cur, queue[qhead]);
        int d = qdist[qhead];
        qhead++;

        if (!strcmp(cur, t)) { printf("%d\n", d); return 0; }

        for (int i = 0; i < n; i++) {
            char nxt[MAXN+1];
            strcpy(nxt, cur);
            nxt[i] ^= 1; // flip '0'^1='1', '1'^1='0'... wait '0'=48, '1'=49
            nxt[i] = (cur[i] == '0') ? '1' : '0';
            // check validity
            int ok = 1;
            for (int j = 0; j <= n-3; j++)
                if (nxt[j]==nxt[j+1] && nxt[j+1]==nxt[j+2]) { ok=0; break; }
            if (!ok) continue;
            if (!visited(nxt, d+1)) {
                strcpy(queue[qtail], nxt);
                qdist[qtail] = d+1;
                qtail++;
            }
        }
    }
    printf("-1\n");
    return 0;
}

