#define MIN(a, b) ((a) < (b) ? (a) : (b))

int main() {
    int n;
    scanf("%d", &n);
    char s[1000005], t[1000005];
    scanf("%s %s", s, t);

    // dp[prev2][prev1] = min cost up to current position
    int dp[2][2];
    for (int a = 0; a < 2; a++)
        for (int b = 0; b < 2; b++)
            dp[a][b] = INT_MAX / 2;

    // Initialize for first character
    dp[0][0] = dp[0][1] = dp[1][0] = dp[1][1] = INT_MAX / 2;
    int first_val = s[0] - '0';
    int target_val = t[0] - '0';
    dp[0][first_val] = (first_val != target_val) ? 1 : 0;

    if (n == 1) {
        printf("%d\n", dp[0][first_val]);
        return 0;
    }

    // For second character
    int ndp[2][2];
    for (int a = 0; a < 2; a++)
        for (int b = 0; b < 2; b++)
            ndp[a][b] = INT_MAX / 2;

    int second_val = s[1] - '0';
    int second_target = t[1] - '0';
    for (int prev = 0; prev < 2; prev++) {
        for (int cur = 0; cur < 2; cur++) {
            if (dp[0][prev] >= INT_MAX / 2) continue;
            int cost = dp[0][prev] + ((cur != second_val) ? 1 : 0) + ((cur != second_target) ? 0 : 0);
            // no triple check since only two chars
            ndp[prev][cur] = cost;
        }
    }
    memcpy(dp, ndp, sizeof(dp));

    // For the rest
    for (int i = 2; i < n; i++) {
        int cur_val = s[i] - '0';
        int cur_target = t[i] - '0';
        for (int a = 0; a < 2; a++)
            for (int b = 0; b < 2; b++)
                ndp[a][b] = INT_MAX / 2;

        for (int p2 = 0; p2 < 2; p2++) {
            for (int p1 = 0; p1 < 2; p1++) {
                if (dp[p2][p1] >= INT_MAX / 2) continue;
                for (int cur = 0; cur < 2; cur++) {
                    if (p2 == p1 && p1 == cur) continue; // no three in a row
                    int cost = dp[p2][p1] + ((cur != cur_val) ? 1 : 0);
                    // we only add inversion cost here; target cost is implicit in final check
                    // Actually correct: cost is number of inversions; we want s[i] to become t[i]
                    // So we must add inversion if cur != s[i], but we also want cur == t[i] eventually.
                    // However we enforce final s[i] == t[i] by only allowing cur == t[i] at the end.
                    // So we only consider cur == t[i] here.
                    if (cur != (t[i] - '0')) continue;
                    ndp[p1][cur] = MIN(ndp[p1][cur], cost);
                }
            }
        }
        memcpy(dp, ndp, sizeof(dp));
    }

    int ans = INT_MAX;
    for (int a = 0; a < 2; a++)
        for (int b = 0; b < 2; b++)
            ans = MIN(ans, dp[a][b]);

    printf("%d\n", ans);
    return 0;
}

