#define INF 1000000000

static inline int bit(char c) { return c - '0'; }

int main(void) {
    char s[200005], t[200005];
    if (scanf("%s %s", s, t) != 2) return 0;

    int n = (int)strlen(s);

    /* dp[a][b]:
       after processing current prefix, the last two characters of current s are a,b
       and dp[a][b] is the minimum operations needed.
    */
    int dp[2][2], ndp[2][2];

    if (n == 1) {
        printf("%d\n", s[0] != t[0]);
        return 0;
    }

    for (int a = 0; a < 2; ++a)
        for (int b = 0; b < 2; ++b)
            dp[a][b] = INF;

    int s0 = bit(s[0]), s1 = bit(s[1]);
    int t0 = bit(t[0]), t1 = bit(t[1]);

    /* First two positions can be adjusted independently because no triple can appear yet. */
    dp[t0][t1] = (s0 != t0) + (s1 != t1);

    for (int i = 2; i < n; ++i) {
        for (int a = 0; a < 2; ++a)
            for (int b = 0; b < 2; ++b)
                ndp[a][b] = INF;

        int want = bit(t[i]);
        int cur = bit(s[i]);

        for (int a = 0; a < 2; ++a) {
            for (int b = 0; b < 2; ++b) {
                if (dp[a][b] == INF) continue;

                /* Final value at position i must equal t[i]. */
                int c = want;

                /* Operation is valid only if resulting string still has no triple ending at i. */
                if (a == b && b == c) continue;

                int cost = dp[a][b] + (cur != c);
                if (cost < ndp[b][c]) ndp[b][c] = cost;
            }
        }

        for (int a = 0; a < 2; ++a)
            for (int b = 0; b < 2; ++b)
                dp[a][b] = ndp[a][b];
    }

    int ans = INF;
    for (int a = 0; a < 2; ++a)
        for (int b = 0; b < 2; ++b)
            if (dp[a][b] < ans) ans = dp[a][b];

    printf("%d\n", ans);
    return 0;
}

import java.util.*;

public class Main {
    static int N;

    static boolean isValid(int mask) {
        for (int i = 0; i + 2 < N; i++) {
            int a = (mask >> i) & 1;
            int b = (mask >> (i+1)) & 1;
            int c = (mask >> (i+2)) & 1;
            if (a == b && b == c) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();
        N = s.length();

        int start = 0, target = 0;
        for (int i = 0; i < N; i++) {
            if (s.charAt(i) == '1') start |= (1 << i);
            if (t.charAt(i) == '1') target |= (1 << i);
        }

        if (start == target) { System.out.println(0); return; }

        Map<Integer, Integer> dist = new HashMap<>();
        Queue<Integer> queue = new LinkedList<>();
        dist.put(start, 0);
        queue.add(start);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            int d = dist.get(cur);

            for (int i = 0; i < N; i++) {
                int next = cur ^ (1 << i);
                if (!isValid(next)) continue;
                if (dist.containsKey(next)) continue;
                dist.put(next, d + 1);
                if (next == target) {
                    System.out.println(d + 1);
                    return;
                }
                queue.add(next);
            }
        }

        System.out.println(-1); // shouldn't happen
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        String t = sc.next();
        sc.close();

        char[] arr = s.toCharArray();
        int ops = 0;

        for (int i = 0; i < n; i++) {
            if (arr[i] == t.charAt(i)) continue;

            // Try flipping directly
            if (canFlip(arr, i)) {
                arr[i] = t.charAt(i);
                ops++;
            } else {
                // Must flip neighbor to break triple
                if (i + 1 < n && arr[i + 1] != t.charAt(i + 1) && canFlip(arr, i + 1)) {
                    arr[i + 1] = t.charAt(i + 1);
                    ops++;
                    i--; // recheck current position
                } else if (i > 0 && canFlip(arr, i - 1)) {
                    arr[i - 1] = (arr[i - 1] == '0' ? '1' : '0');
                    ops++;
                    i -= 2; // recheck from before
                }
            }
        }

        System.out.println(ops);
    }

    static boolean canFlip(char[] arr, int idx) {
        char orig = arr[idx];
        char flipped = (orig == '0' ? '1' : '0');
        arr[idx] = flipped;

        boolean ok = true;
        if (idx >= 2 && arr[idx] == arr[idx - 1] && arr[idx] == arr[idx - 2]) ok = false;
        if (idx >= 1 && idx + 1 < arr.length && arr[idx] == arr[idx - 1] && arr[idx] == arr[idx + 1]) ok = false;
        if (idx + 2 < arr.length && arr[idx] == arr[idx + 1] && arr[idx] == arr[idx + 2]) ok = false;

        arr[idx] = orig; // revert
        return ok;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        String t = fs.next();

        int n = s.length();

        // DP over position.
        // State: last two characters of the current built string after processing i chars.
        // Since valid strings never contain 3 equal consecutive chars,
        // when appending a bit we only need to ensure it doesn't make xxx.
        //
        // For i = 0, handle separately.
        // For i >= 1, dp[a][b] = min cost after processing up to current position,
        // where previous two bits are a, b.
        int[][] dp = new int[2][2];
        for (int[] row : dp) Arrays.fill(row, INF);

        // position 0
        for (int b = 0; b <= 1; b++) {
            if (b == bit(t.charAt(0))) {
                // final string must equal t, so chosen bit must be t[0]
                // flipping is allowed for a single char (cannot create triple)
                int cost = (b == bit(s.charAt(0))) ? 0 : 1;
                if (n == 1) {
                    System.out.println(cost);
                    return;
                }
                // initialize later with position 1
            }
        }

        // position 1 initialization
        for (int b0 = 0; b0 <= 1; b0++) {
            if (b0 != bit(t.charAt(0))) continue;
            int cost0 = (b0 == bit(s.charAt(0))) ? 0 : 1;

            for (int b1 = 0; b1 <= 1; b1++) {
                if (b1 != bit(t.charAt(1))) continue;
                int cost1 = (b1 == bit(s.charAt(1))) ? 0 : 1;
                dp[b0][b1] = Math.min(dp[b0][b1], cost0 + cost1);
            }
        }

        for (int i = 2; i < n; i++) {
            int[][] ndp = new int[2][2];
            for (int[] row : ndp) Arrays.fill(row, INF);

            int x = bit(t.charAt(i)); // final bit must be t[i]

            for (int a = 0; a <= 1; a++) {
                for (int b = 0; b <= 1; b++) {
                    int cur = dp[a][b];
                    if (cur >= INF) continue;

                    // append x, must not create a triple in final/current string
                    if (a == b && b == x) continue;

                    int add = (x == bit(s.charAt(i))) ? 0 : 1;
                    ndp[b][x] = Math.min(ndp[b][x], cur + add);
                }
            }
            dp = ndp;
        }

        int ans = INF;
        for (int a = 0; a <= 1; a++) {
            for (int b = 0; b <= 1; b++) {
                ans = Math.min(ans, dp[a][b]);
            }
        }

        System.out.println(ans);
    }

    static int bit(char c) {
        return c - '0';
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

from collections import deque

def solve():
    import sys
    input_data = sys.stdin.read().split()
    s = input_data[0]
    t = input_data[1]

    if s == t:
        print(0)
        return

    n = len(s)

    def is_valid(st):
        for i in range(len(st) - 2):
            if st[i] == st[i+1] == st[i+2]:
                return False
        return True

    def get_neighbors(st):
        result = []
        lst = list(st)
        for i in range(n):
            lst[i] = '1' if lst[i] == '0' else '0'
            ns = ''.join(lst)
            if is_valid(ns):
                result.append(ns)
            lst[i] = '1' if lst[i] == '0' else '0'
        return result

    # BFS
    dist = {s: 0}
    queue = deque([s])

    while queue:
        cur = queue.popleft()
        d = dist[cur]

        for nxt in get_neighbors(cur):
            if nxt == t:
                print(d + 1)
                return
            if nxt not in dist:
                dist[nxt] = d + 1
                queue.append(nxt)

    print(-1)  # shouldn't happen if t is reachable

solve()
